head.script:
scwin.trigger2_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var url = "popup_modal_modaless_WPFF-286_(WSQ-3669)_sub2.xml";
    var options = {};
    options.id = "test";
    options.type = "litewindow";
    options.width = "300px";
    options.height = "400px";
    options.modal = "true";
    options.frameMode = "wframe";
    WebSquare.util.openPopup(url, options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('test_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('aaaaa1_close').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'_modal').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    scwin.init = {};
    init.initinput = input1.setValue("hh");
}
